51	    public void afterPropertiesSet() {
52	        if (defaultAuthMode == AuthMode.JWT_AND_HMAC) {
53	            throw new IllegalStateException(
54	                    "maritime.gateway.security.default-auth-mode=JWT_AND_HMAC is reserved and not yet implemented");
55	        }
56	        for (RoutePolicy rp : routes) {
57	            if (rp.authMode == null) {
58	                throw new IllegalStateException(
59	                        "Route '" + rp.id + "' is missing required auth-mode. "
60	                        + "Set maritime.gateway.security.routes[" + routes.indexOf(rp) + "].auth-mode "
61	                        + "to one of: JWT, HMAC, JWT_OR_HMAC, NONE");
62	            }
63	            if (rp.authMode == AuthMode.JWT_AND_HMAC) {
64	                throw new IllegalStateException(
65	                        "Route '" + rp.id + "' uses JWT_AND_HMAC which is reserved and not yet implemented");
66	            }
67	        }
68	        if (jwt.enabled) {
69	            if (jwt.secret == null || jwt.secret.isBlank()) {
70	                throw new IllegalStateException(
71	                        "maritime.gateway.security.jwt.secret must not be blank when jwt.enabled=true");
72	            }
73	            if (jwt.issuer == null || jwt.issuer.isBlank()) {
74	                throw new IllegalStateException(
75	                        "maritime.gateway.security.jwt.issuer must not be blank when jwt.enabled=true");
76	            }
77	        }
78	        if (hmac.enabled) {
79	            if (hmac.timestampTolerance == null || hmac.timestampTolerance.isNegative()) {
80	                throw new IllegalStateException(
81	                        "maritime.gateway.security.hmac.timestamp-tolerance must be a positive duration when hmac.enabled=true");
82	            }
83	            if (hmac.nonceTtl == null || hmac.nonceTtl.isNegative()) {
84	                throw new IllegalStateException(
85	                        "maritime.gateway.security.hmac.nonce-ttl must be a positive duration when hmac.enabled=true");
86	            }
87	        }
88	    }
